import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:weft_document/weft_document.dart';
import 'package:weft_engine/weft_engine.dart';

/// Browser golden geometry baseline for the `float_image` conformance case.
///
/// The reference JSON is generated by `tool/browser_references.mjs` with the
/// pinned Roboto fixtures and committed under `conformance/reference/`.
/// Regenerate with:
///   node tool/browser_references.mjs --case float_image
///   cp build/conformance/browser/geometry/float_image.json \
///      conformance/reference/float_image.geometry.json
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  final root = _workspaceRoot();
  final referencePath =
      '${root.path}/conformance/reference/float_image.geometry.json';
  final reference = jsonDecode(File(referencePath).readAsStringSync())
      as Map<String, dynamic>;

  late ui.Image floatLeft;
  late ui.Image floatRight;
  late ui.Image blockHero;

  setUpAll(() async {
    await _loadFonts(root);
    floatLeft = await _decodePng(
      '${root.path}/conformance/assets/float_left.png',
    );
    floatRight = await _decodePng(
      '${root.path}/conformance/assets/float_right.png',
    );
    blockHero = await _decodePng(
      '${root.path}/conformance/assets/block_hero.png',
    );
  });

  tearDownAll(() {
    floatLeft.dispose();
    floatRight.dispose();
    blockHero.dispose();
  });

  WeftDocumentSnapshot normalizeCase() {
    final source = File(
      '${root.path}/conformance/cases/float_image.html',
    ).readAsStringSync();
    final document = const WeftNormalizer().normalize(
      source,
      id: 'float-image-geometry',
    );
    expect(document.supportReport.canRender, isTrue);
    expect(document.body, isNotNull);
    return document;
  }

  Map<int, ui.Image> imageMap(WeftDocumentSnapshot document) {
    final images = <int, ui.Image>{};
    void visit(WeftNode node) {
      if (node is WeftElement) {
        if (node.tag == 'img') {
          final src = node.attribute('src') ?? '';
          if (src.endsWith('float_left.png')) {
            images[node.id] = floatLeft;
          } else if (src.endsWith('float_right.png')) {
            images[node.id] = floatRight;
          } else if (src.endsWith('block_hero.png')) {
            images[node.id] = blockHero;
          }
        }
        for (final child in node.children) {
          visit(child);
        }
      }
    }

    visit(document.body!);
    expect(images, hasLength(3));
    return images;
  }

  test('block and image geometry matches the Chrome reference', () {
    final document = normalizeCase();
    final layout = const WeftLayoutEngine().layout(
      document,
      width: 360,
      images: imageMap(document),
    );
    addTearDown(layout.dispose);

    final elements = (reference['elements'] as Map<String, dynamic>)
        .cast<String, Map<String, dynamic>>();
    // Direct body children in document order map 1:1 to the reference keys.
    const expectedOrder = [
      'title',
      'intro',
      'wrap-latin',
      'between',
      'wrap-opposing',
      'cleared',
      'divider',
      'hero',
      'caption',
    ];
    final bodyChildren = document.body!.children
        .whereType<WeftElement>()
        .where((element) => element.tag != 'img')
        .toList();
    expect(bodyChildren.map((element) => element.tag), [
      'h2',
      'p',
      'p',
      'p',
      'p',
      'p',
      'hr',
      'p',
    ]);
    // The hero image is a direct body child between the divider and caption.
    final hero = document.body!.children
        .whereType<WeftElement>()
        .firstWhere((element) => element.tag == 'img');
    final orderedIds = <int>[
      ...bodyChildren.take(6).map((element) => element.id),
      bodyChildren[6].id, // divider
      hero.id,
      bodyChildren[7].id, // caption
    ];

    final boxesById = <int, Rect>{
      for (final box in layout.boxes) box.nodeId: box.rect,
    };
    for (var index = 0; index < expectedOrder.length; index++) {
      final key = expectedOrder[index];
      final expected = _elementRect(elements, key);
      final actual = boxesById[orderedIds[index]];
      expect(
        actual,
        isNotNull,
        reason: 'No layout box for reference element "$key".',
      );
      expectRectClose(actual!, expected, 0.5, label: key);
    }

    // The two floats are img children inside their wrapping paragraphs.
    final floats = <String, Rect>{
      'float-left': _imageBox(layout, document, 'float_left.png'),
      'float-right': _imageBox(layout, document, 'float_right.png'),
    };
    expectRectClose(
        floats['float-left']!, _elementRect(elements, 'float-left'), 0.5,
        label: 'float-left');
    expectRectClose(
        floats['float-right']!, _elementRect(elements, 'float-right'), 0.5,
        label: 'float-right');

    final documentHeight = (reference['documentHeight'] as num).toDouble();
    expect(
      layout.size.height,
      moreOrLessEquals(documentHeight, epsilon: 1),
      reason: 'Document scroll height diverged from the Chrome reference.',
    );
  });

  test('text lines avoid float exclusions and match Chrome line geometry', () {
    final document = normalizeCase();
    final layout = const WeftLayoutEngine().layout(
      document,
      width: 360,
      images: imageMap(document),
    );
    addTearDown(layout.dispose);

    final elements = (reference['elements'] as Map<String, dynamic>)
        .cast<String, Map<String, dynamic>>();
    final floatLeftBox = _imageBox(layout, document, 'float_left.png');
    final floatRightBox = _imageBox(layout, document, 'float_right.png');
    // Margin boxes from the case file: left float uses margin 0 16px 8px 0,
    // right float uses margin 0 0 8px 16px.
    final leftExclusion = Rect.fromLTRB(
      floatLeftBox.left,
      floatLeftBox.top,
      floatLeftBox.right + 16,
      floatLeftBox.bottom + 8,
    );
    final rightExclusion = Rect.fromLTRB(
      floatRightBox.left - 16,
      floatRightBox.top,
      floatRightBox.right,
      floatRightBox.bottom + 8,
    );
    expectRectClose(
      leftExclusion,
      _chromeExclusion(elements, 'float-left', right: 16, bottom: 8),
      0.5,
      label: 'float-left margin box',
    );
    expectRectClose(
      rightExclusion,
      _chromeExclusion(elements, 'float-right', left: 16, bottom: 8),
      0.5,
      label: 'float-right margin box',
    );

    final lines = _visibleTextLines(layout);
    expect(lines, isNotEmpty);
    for (final line in lines) {
      final rect = Rect.fromLTWH(
        line.offset.dx,
        line.offset.dy,
        line.painter.width,
        line.painter.height,
      );
      for (final exclusion in [leftExclusion, rightExclusion]) {
        final overlapsVertically = rect.top < exclusion.bottom - 0.5 &&
            rect.bottom > exclusion.top + 0.5;
        if (!overlapsVertically) continue;
        expect(
          rect.right <= exclusion.left + 0.5 ||
              rect.left >= exclusion.right - 0.5,
          isTrue,
          reason: 'Line at ${line.offset} intersects float exclusion '
              '$exclusion.',
        );
      }
    }

    // A line must run beside the left float and below it use full width.
    expect(
      lines.any((line) => line.offset.dx >= leftExclusion.right - 0.5),
      isTrue,
      reason: 'No text line was shortened beside the left float.',
    );
    expect(
      lines.any((line) => line.offset.dx == 0),
      isTrue,
      reason: 'No text line returned to the full content width.',
    );

    _expectLineGeometry(
      layout,
      document,
      reference,
      paragraphMatcher: (text) => text.contains('whiskey'),
      firstLineLeft: 136,
      label: 'wrap-latin',
    );
    _expectLineGeometry(
      layout,
      document,
      reference,
      paragraphMatcher: (text) => text.endsWith('foxtrot'),
      firstLineLeft: 0,
      label: 'wrap-opposing',
    );
  });

  test('late image resolution converges to the canonical float geometry', () {
    final document = normalizeCase();
    const engine = WeftLayoutEngine();

    // Before resolution the images collapse to empty alt text, so no float
    // exclusions exist and every line keeps the full content width.
    final unresolved = engine.layout(document, width: 360);
    addTearDown(unresolved.dispose);
    expect(
      unresolved.commands.whereType<WeftImagePaintCommand>(),
      isEmpty,
    );
    for (final line in _visibleTextLines(unresolved)) {
      expect(line.offset.dx, 0,
          reason: 'Unresolved floats must not shift '
              'lines.');
    }

    // Resolving later must produce byte-identical geometry to laying out with
    // the images present from the start.
    final resolvedAfterDelay = engine.layout(
      document,
      width: 360,
      images: imageMap(document),
    );
    addTearDown(resolvedAfterDelay.dispose);
    final canonical = engine.layout(
      document,
      width: 360,
      images: imageMap(document),
    );
    addTearDown(canonical.dispose);

    expect(resolvedAfterDelay.size, canonical.size);
    expect(
      resolvedAfterDelay.boxes.map((box) => box.rect),
      canonical.boxes.map((box) => box.rect),
    );
    final resolvedLines = _visibleTextLines(resolvedAfterDelay);
    final canonicalLines = _visibleTextLines(canonical);
    expect(resolvedLines, hasLength(canonicalLines.length));
    for (var index = 0; index < canonicalLines.length; index++) {
      expect(resolvedLines[index].offset, canonicalLines[index].offset);
      expect(
        resolvedLines[index].painter.text?.toPlainText(),
        canonicalLines[index].painter.text?.toPlainText(),
      );
    }
    final resolvedImages =
        resolvedAfterDelay.commands.whereType<WeftImagePaintCommand>().toList();
    final canonicalImages =
        canonical.commands.whereType<WeftImagePaintCommand>().toList();
    expect(resolvedImages, hasLength(canonicalImages.length));
    for (var index = 0; index < canonicalImages.length; index++) {
      expect(resolvedImages[index].destination,
          canonicalImages[index].destination);
    }
  });
}

Rect _elementRect(Map<String, Map<String, dynamic>> elements, String key) {
  final element = elements[key];
  expect(element, isNotNull, reason: 'Reference is missing "$key".');
  return Rect.fromLTWH(
    (element!['left'] as num).toDouble(),
    (element['top'] as num).toDouble(),
    (element['width'] as num).toDouble(),
    (element['height'] as num).toDouble(),
  );
}

Rect _chromeExclusion(
  Map<String, Map<String, dynamic>> elements,
  String key, {
  double left = 0,
  double right = 0,
  double bottom = 0,
}) {
  final box = _elementRect(elements, key);
  return Rect.fromLTRB(
    box.left - left,
    box.top,
    box.right + right,
    box.bottom + bottom,
  );
}

Rect _imageBox(
  WeftLayoutResult layout,
  WeftDocumentSnapshot document,
  String srcSuffix,
) {
  WeftElement? image;
  void visit(WeftNode node) {
    if (node is WeftElement) {
      if (node.tag == 'img' &&
          (node.attribute('src') ?? '').endsWith(srcSuffix)) {
        image = node;
      }
      for (final child in node.children) {
        visit(child);
      }
    }
  }

  visit(document.body!);
  expect(image, isNotNull, reason: 'No img with src ending "$srcSuffix".');
  return layout.boxes.singleWhere((box) => box.nodeId == image!.id).rect;
}

List<WeftTextPaintCommand> _visibleTextLines(WeftLayoutResult layout) {
  return layout.commands
      .whereType<WeftTextPaintCommand>()
      .where(
        (command) => (command.painter.text?.toPlainText() ?? '').isNotEmpty,
      )
      .toList();
}

void expectRectClose(Rect actual, Rect expected, double epsilon,
    {required String label}) {
  expect(
    actual.left,
    moreOrLessEquals(expected.left, epsilon: epsilon),
    reason: '$label left diverged from Chrome.',
  );
  expect(
    actual.top,
    moreOrLessEquals(expected.top, epsilon: epsilon),
    reason: '$label top diverged from Chrome.',
  );
  expect(
    actual.width,
    moreOrLessEquals(expected.width, epsilon: epsilon),
    reason: '$label width diverged from Chrome.',
  );
  expect(
    actual.height,
    moreOrLessEquals(expected.height, epsilon: epsilon),
    reason: '$label height diverged from Chrome.',
  );
}

void _expectLineGeometry(
  WeftLayoutResult layout,
  WeftDocumentSnapshot document,
  Map<String, dynamic> reference, {
  required bool Function(String text) paragraphMatcher,
  required double firstLineLeft,
  required String label,
}) {
  final words =
      (reference['words'] as Map<String, dynamic>)[label] as List<dynamic>;
  expect(words, isNotEmpty, reason: 'Reference is missing words for $label.');

  // Chrome word boxes are grouped into visual lines by their box top.
  final chromeLines = <_ReferenceLine>[];
  for (final token in words) {
    final entry = token as Map<String, dynamic>;
    final rect =
        (entry['rects'] as List<dynamic>).first as Map<String, dynamic>;
    final top = (rect['top'] as num).toDouble();
    final left = (rect['left'] as num).toDouble();
    final right = (rect['right'] as num).toDouble();
    final line = chromeLines.isEmpty || (chromeLines.last.top - top).abs() >= 2
        ? null
        : chromeLines.last;
    if (line != null) {
      line
        ..left = math.min(line.left, left)
        ..right = math.max(line.right, right);
    } else {
      chromeLines.add(_ReferenceLine(top: top, left: left, right: right));
    }
  }

  final paragraphId = _paragraphIdByText(layout, document, paragraphMatcher);
  final weftLines = layout.commands
      .whereType<WeftTextPaintCommand>()
      .where((command) => command.nodeId == paragraphId)
      .where(
        (command) => (command.painter.text?.toPlainText() ?? '').isNotEmpty,
      )
      .toList();
  // Ignore the reference lines: they cover only the words beside and below
  // the float, which is exactly what the paragraph paints.
  expect(weftLines, hasLength(chromeLines.length),
      reason: '$label line count diverged from Chrome.');
  expect(
    weftLines.first.offset.dx,
    moreOrLessEquals(firstLineLeft, epsilon: 1),
    reason: '$label first line left diverged from Chrome.',
  );

  for (var index = 0; index < chromeLines.length; index++) {
    final chrome = chromeLines[index];
    final painter = weftLines[index].painter;
    final offset = weftLines[index].offset;
    final boxes = painter.getBoxesForSelection(
      TextSelection(baseOffset: 0, extentOffset: painter.plainText.length),
    );
    expect(boxes, isNotEmpty);
    final left = boxes.map((box) => box.left).reduce(math.min) + offset.dx;
    final right = boxes.map((box) => box.right).reduce(math.max) + offset.dx;
    final top = boxes.map((box) => box.top).reduce(math.min) + offset.dy;
    expect(left, moreOrLessEquals(chrome.left, epsilon: 1.5),
        reason: '$label line $index left diverged from Chrome.');
    expect(right, moreOrLessEquals(chrome.right, epsilon: 1.5),
        reason: '$label line $index right diverged from Chrome.');
    expect(top, moreOrLessEquals(chrome.top, epsilon: 1.5),
        reason: '$label line $index top diverged from Chrome.');
  }
}

int _paragraphIdByText(
  WeftLayoutResult layout,
  WeftDocumentSnapshot document,
  bool Function(String text) matcher,
) {
  final matches = <int>[];
  void visit(WeftNode node) {
    if (node is WeftElement) {
      if (node.tag == 'p') {
        final buffer = StringBuffer();
        for (final child in node.children) {
          if (child is WeftText) buffer.write(child.text);
        }
        if (matcher(buffer.toString())) matches.add(node.id);
      }
      for (final child in node.children) {
        visit(child);
      }
    }
  }

  visit(document.body!);
  expect(matches, hasLength(1),
      reason: 'Expected exactly one matching '
          'paragraph.');
  return matches.single;
}

Future<ui.Image> _decodePng(String path) async {
  final bytes = await File(path).readAsBytes();
  final completer = Completer<ui.Image>();
  ui.decodeImageFromList(bytes, completer.complete);
  return completer.future;
}

Future<void> _loadFonts(Directory root) async {
  final fontDir = '${root.path}/conformance/fonts';
  final roboto = FontLoader('WeftRoboto');
  for (final file in const [
    'Roboto-Regular.ttf',
    'Roboto-Bold.ttf',
    'Roboto-Italic.ttf',
    'Roboto-BoldItalic.ttf',
  ]) {
    final bytes = await File('$fontDir/$file').readAsBytes();
    roboto.addFont(Future.value(ByteData.sublistView(bytes)));
  }
  await roboto.load();

  final mono = FontLoader('WeftRobotoMono');
  for (final file in const [
    'RobotoMono-Regular.ttf',
    'RobotoMono-Bold.ttf',
  ]) {
    final bytes = await File('$fontDir/$file').readAsBytes();
    mono.addFont(Future.value(ByteData.sublistView(bytes)));
  }
  await mono.load();
}

class _ReferenceLine {
  _ReferenceLine({
    required this.top,
    required this.left,
    required this.right,
  });

  final double top;
  double left;
  double right;
}

Directory _workspaceRoot() {
  var current = Directory.current.absolute;
  while (true) {
    final pubspec = File('${current.path}/pubspec.yaml');
    if (pubspec.existsSync() &&
        pubspec.readAsStringSync().contains(
              RegExp(r'^workspace:', multiLine: true),
            )) {
      return current;
    }
    final parent = current.parent;
    if (parent.path == current.path) {
      throw StateError('Could not find the Weft workspace root.');
    }
    current = parent;
  }
}
